}{}\begin{equation*} \mathrm{PRS}\ = {\mathop \sum \nolimits_i^m {\beta _i}\left( {\mathop \sum \nolimits_{j = 0}^2 {\omega _{ij}} \times j} \right)}, \end{equation*}\end{document}where \documentclass[12pt]{minimal}
